import permutationsHeap from '../../src/permutations_heap';

describe('permutationsHeap', () => {
  test.skip('should generate all permutations for array with 3 numbers', () => {
    const input = [1, 2, 3];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toHaveLength(6); // 3! = 6

    // Check that all permutations are unique
    const stringified = result.map(arr => arr.join(','));
    expect([...new Set(stringified)]).toHaveLength(6);

    // Verify all contain the same elements
    result.forEach(perm => {
      expect(perm.slice().sort()).toEqual([1, 2, 3]);
    });

    // Verify original array is unchanged
    expect(input).toEqual(inputCopy);
  });

  test.skip('should generate all permutations for array with 4 numbers', () => {
    const input = [1, 2, 3, 4];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toHaveLength(24); // 4! = 24

    // Check that all permutations are unique
    const stringified = result.map(arr => arr.join(','));
    expect([...new Set(stringified)]).toHaveLength(24);

    // Verify all contain the same elements
    result.forEach(perm => {
      expect(perm.slice().sort()).toEqual([1, 2, 3, 4]);
    });

    // Verify original array is unchanged
    expect(input).toEqual(inputCopy);
  });

  test('should handle empty array', () => {
    const input = [];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toEqual([[]]);
    expect(input).toEqual(inputCopy);
  });

  test('should handle single element array', () => {
    const input = [42];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toEqual([[42]]);
    expect(input).toEqual(inputCopy);
  });

  test.skip('should handle array with duplicate elements', () => {
    const input = [1, 1, 2];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toHaveLength(6); // 3! = 6

    // With duplicate elements, we expect fewer unique permutations
    const stringified = result.map(arr => arr.join(','));
    expect([...new Set(stringified)]).toHaveLength(3);

    expect(input).toEqual(inputCopy);
  });

  test.skip('should work with string elements', () => {
    const input = ['a', 'b', 'c'];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toHaveLength(6); // 3! = 6

    // Check that all permutations are unique
    const stringified = result.map(arr => arr.join(','));
    expect([...new Set(stringified)]).toHaveLength(6);

    expect(input).toEqual(inputCopy);
  });

  test.skip('should work with mixed type elements', () => {
    const input = [1, 'a', null];
    const inputCopy = [...input];
    const result = permutationsHeap(input);

    expect(result).toHaveLength(6); // 3! = 6

    // Verify all permutations contain the same elements
    result.forEach(perm => {
      expect(perm).toEqual(expect.arrayContaining([1, 'a', null]));
      expect(perm).toHaveLength(3);
    });

    expect(input).toEqual(inputCopy);
  });

  test.skip('should maintain original array unchanged', () => {
    const input = [1, 2, 3, 4, 5];
    const inputCopy = [...input];
    permutationsHeap(input);

    expect(input).toEqual(inputCopy);
  });

  test('should throw TypeError for non-array input', () => {
    expect(() => permutationsHeap(null)).toThrow(TypeError);
    expect(() => permutationsHeap(undefined)).toThrow(TypeError);
    expect(() => permutationsHeap('string')).toThrow(TypeError);
    expect(() => permutationsHeap(123)).toThrow(TypeError);
    expect(() => permutationsHeap({})).toThrow(TypeError);
  });
});

