import combinationsReplacement from '../../src/combinations_replacement';

describe('combinationsReplacement', () => {
  test('should generate all combinations of length 2 from [1, 2, 3] with replacement', () => {
    const input = [1, 2, 3];
    const k = 2;
    const expected = [
      [1, 1],
      [1, 2],
      [1, 3],
      [2, 2],
      [2, 3],
      [3, 3]
    ];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should generate all combinations of length 3 from [1, 2] with replacement', () => {
    const input = [1, 2];
    const k = 3;
    const expected = [
      [1, 1, 1],
      [1, 1, 2],
      [1, 2, 2],
      [2, 2, 2]
    ];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should return combinations when k is greater than array length', () => {
    const input = [1, 2];
    const k = 5;
    const expected = [
      [1, 1, 1, 1, 1],
      [1, 1, 1, 1, 2],
      [1, 1, 1, 2, 2],
      [1, 1, 2, 2, 2],
      [1, 2, 2, 2, 2],
      [2, 2, 2, 2, 2]
    ];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should handle single element array', () => {
    const input = [1];
    const k = 3;
    const expected = [[1, 1, 1]];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should handle k = 1', () => {
    const input = [1, 2, 3];
    const k = 1;
    const expected = [[1], [2], [3]];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should handle empty array', () => {
    const input = [];
    const k = 2;
    const expected = [];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test.skip('should return empty array when k = 0', () => {
    const input = [1, 2, 3];
    const k = 0;
    const expected = [];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should work with string elements', () => {
    const input = ['a', 'b'];
    const k = 2;
    const expected = [
      ['a', 'a'],
      ['a', 'b'],
      ['b', 'b']
    ];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should work with mixed type elements', () => {
    const input = [1, 'a', true];
    const k = 2;
    const expected = [
      [1, 1],
      [1, 'a'],
      [1, true],
      ['a', 'a'],
      ['a', true],
      [true, true]
    ];
    expect(combinationsReplacement(input, k)).toEqual(expected);
  });

  test('should not modify the original array', () => {
    const input = [1, 2, 3];
    const originalInput = [...input];
    combinationsReplacement(input, 2);
    expect(input).toEqual(originalInput);
  });
});

