import poissonDistribution from '../../src/poisson_distribution';

describe('poissonDistribution', () => {
  test('should return undefined for lambda <= 0', () => {
    expect(poissonDistribution(0)).toBeUndefined();
    expect(poissonDistribution(-1)).toBeUndefined();
    expect(poissonDistribution(-0.5)).toBeUndefined();
  });

  test('should return an array for valid lambda values', () => {
    const result = poissonDistribution(1);
    expect(result).toBeInstanceOf(Array);
    expect(result.length).toBeGreaterThan(0);
  });

  test('should return probabilities that sum to approximately 1', () => {
    const result = poissonDistribution(2);
    const sum = result.reduce((acc, prob) => acc + prob, 0);
    expect(sum).toBeCloseTo(1, 3);
  });

  test('should handle small lambda values correctly', () => {
    const result = poissonDistribution(0.5);
    const sum = result.reduce((acc, prob) => acc + prob, 0);
    expect(sum).toBeCloseTo(1, 3);
    expect(result.length).toBeGreaterThan(0);
  });

  test('should handle larger lambda values correctly', () => {
    const result = poissonDistribution(5);
    const sum = result.reduce((acc, prob) => acc + prob, 0);
    expect(sum).toBeCloseTo(1, 3);
    expect(result.length).toBeGreaterThan(0);
  });

  test('should return decreasing probabilities for large outcomes', () => {
    const result = poissonDistribution(3);
    // Check that probabilities generally decrease after the peak
    let peakFound = false;
    for (let i = 1; i < result.length - 1; i++) {
      if (result[i] >= result[i-1] && result[i] >= result[i+1]) {
        peakFound = true;
      }
      if (peakFound && i > 1) {
        // After peak, probabilities should generally decrease
        expect(result[i]).toBeGreaterThanOrEqual(result[i+1] * 0.9); // Allow small variations due to floating point
      }
    }
    expect(peakFound).toBe(true);
  });

  test('should produce consistent results for the same lambda', () => {
    const result1 = poissonDistribution(2.5);
    const result2 = poissonDistribution(2.5);
    expect(result1).toEqual(result2);
  });

  test('should handle integer lambda values correctly', () => {
    const result = poissonDistribution(4);
    const sum = result.reduce((acc, prob) => acc + prob, 0);
    expect(sum).toBeCloseTo(1, 3);
    expect(result.length).toBeGreaterThan(0);
  });
});
